ExpandableReorderableList<ValueKey<int>>(
  onReorder: (details) {
    setState(() {
      var newIndex = details.newIndex;
      if (details.oldIndex < details.newIndex) newIndex -= 1;
      final item = _items.removeAt(details.oldIndex);
      _items.insert(newIndex, item);
    });
  },
  children: _items.map((int item) {
    return ExpandableReorderableListItem<ValueKey<int>>(
      key: ValueKey<int>(item),
      builder: (_, child, model) {
        return ReorderableDragStartListener(
          index: model.index!,
          child: ListTile(title: Text('Item $item')),
        );
      },
    );
  }).toList(),
);
